package dev.rodrigosambade.seats;
import dev.rodrigosambade.net.ConnectivityAndInternetAccess;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.time.Duration;
public final class SeatClient{public static String reserve(String host,int port,int row,int col)throws IOException{ConnectivityAndInternetAccess.requireInternetForRemoteHost(host,Duration.ofSeconds(2));try(Socket s=new Socket()){s.connect(new InetSocketAddress(host,port),3000);try(var in=new BufferedReader(new InputStreamReader(s.getInputStream(),StandardCharsets.UTF_8));var out=new BufferedWriter(new OutputStreamWriter(s.getOutputStream(),StandardCharsets.UTF_8))){out.write("RESERVE "+row+" "+col);out.newLine();out.flush();return in.readLine();}}}public static void main(String[]a)throws Exception{if(a.length<2)throw new IllegalArgumentException("host port");var c=new BufferedReader(new InputStreamReader(System.in));System.out.print("Fila (0-3): ");int r=Integer.parseInt(c.readLine());System.out.print("Asiento (0-3): ");int s=Integer.parseInt(c.readLine());System.out.println(reserve(a[0],Integer.parseInt(a[1]),r,s));}}
